//! `docs/drift.html`, the guided page that shows what drift does, stays true to the tool (unit P-2, ADR 0040 and ADR 0052).
//!
//! The page is generated by `tools/demo/drift_page.py`: a hand-written template (`tools/demo/drift.html`, the same bytes for
//! every corpus) with one JSON document inserted. The document is computed from what is already committed under
//! `docs/architecture/drift/` (the three edits, each edit's `satisfy.txt` and overlay) plus one `req compare` run per edit on
//! a throw-away copy. It is checked the way the explorer is: regenerated and compared. What a test can read back is the data
//! document and the template around it; how the script behaves in a browser is not in the gate (the named gap of ADR 0054).
//!
//! The oracles here are written in this file or read from the committed `satisfy.txt` files, never taken from the builder.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

use serde_json::Value;

const PAGE: &str = "docs/drift.html";
const TEMPLATE: &str = "tools/demo/drift.html";
const BUILDER: &str = "tools/demo/drift_page.py";
const EDITS: &str = "docs/architecture/drift/edits.json";
/// The token in the template that the builder replaces with the data document (the only byte the page adds).
const TOKEN: &str = "__REQ_DRIFT_DATA__";
const OPEN: &str = "<script type=\"application/json\" id=\"req-drift-data\">";
const CLAIM: &str = "REQ-0010";
const ELEMENT: &str = "src/bench.rs";

/// What each of the three edits must read, written here from ADR 0040 decision 3 and the O-6 note (never from the builder):
/// (edit id, kind, JSON outcome word, outcome as `req satisfy` prints it, direction `req compare` gives).
const STORIES: [(&str, &str, &str, &str, &str); 3] = [
    ("cosmetic", "re-word", "holds", "HOLDS", "identical"),
    (
        "loosening",
        "loosen",
        "holds_weakened",
        "HOLDS (weakened)",
        "numeric_loosening",
    ),
    (
        "tightening",
        "tighten",
        "suspect",
        "SUSPECT",
        "numeric_tightening",
    ),
];

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).to_path_buf()
}

fn req_bin() -> PathBuf {
    std::env::var_os("CARGO_BIN_EXE_req")
        .map(PathBuf::from)
        .expect("integration tests run with CARGO_BIN_EXE_req set")
}

/// `python3` as an absolute path, resolved before the child's `PATH` is rewritten.
fn python3() -> PathBuf {
    let path = std::env::var_os("PATH").unwrap_or_default();
    for dir in std::env::split_paths(&path) {
        let candidate = dir.join("python3");
        if candidate.is_file() {
            return candidate;
        }
    }
    panic!("python3 is required for tools/demo/drift_page.py - install it first");
}

fn read(path: &Path) -> String {
    fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("{} cannot be read: {error}", path.display()))
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).expect("makes the dir");
    for entry in fs::read_dir(from).unwrap_or_else(|e| panic!("{}: {e}", from.display())) {
        let entry = entry.expect("a dir entry");
        let target = to.join(entry.file_name());
        if entry.file_type().expect("a file type").is_dir() {
            copy_tree(&entry.path(), &target);
        } else {
            fs::copy(entry.path(), &target).expect("copies a file");
        }
    }
}

/// A scratch copy of the parts of the repository the build reads, never this checkout.
struct Copy(PathBuf);

impl Copy {
    fn new(name: &str) -> Self {
        static N: AtomicU64 = AtomicU64::new(0);
        let dir = std::env::temp_dir().join(format!(
            "req-drift-page-{}-{}-{name}",
            std::process::id(),
            N.fetch_add(1, Ordering::SeqCst)
        ));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).expect("creates the scratch dir");
        for tree in [
            "claims",
            "aliases",
            ".req",
            "docs/architecture",
            "docs/adr",
            "tools/demo",
        ] {
            copy_tree(&root().join(tree), &dir.join(tree));
        }
        fs::copy(root().join(PAGE), dir.join(PAGE)).expect("copies the committed page");
        // The pages it links must exist beside it; their content is not read, so a stub stands in for each.
        for linked in [
            "explorer.html",
            "architecture.html",
            "architecture-drift.html",
        ] {
            fs::write(dir.join("docs").join(linked), "<!doctype html>\n").expect("writes a stub");
        }
        Copy(dir)
    }

    fn path(&self, relative: &str) -> PathBuf {
        self.0.join(relative)
    }
}

impl Drop for Copy {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

struct Run {
    code: Option<i32>,
    said: String,
}

/// `python3 <repo>/tools/demo/drift_page.py <args>` with `req` first on `PATH`, run from `repo` (the script reads the
/// repository it lives in, so a copy checks itself).
fn build(repo: &Path, args: &[&str]) -> Run {
    let interpreter = python3();
    let mut entries = vec![req_bin().parent().expect("a parent dir").to_path_buf()];
    entries.extend(std::env::split_paths(
        &std::env::var_os("PATH").unwrap_or_default(),
    ));
    let path = std::env::join_paths(entries).expect("valid PATH");
    let output = Command::new(interpreter)
        .arg(BUILDER)
        .args(args)
        .current_dir(repo)
        .env("PATH", path)
        .env_remove("REQ_ROOT")
        .output()
        .expect("runs tools/demo/drift_page.py");
    Run {
        code: output.status.code(),
        said: format!(
            "{}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        ),
    }
}

/// The data document embedded in a page: the text between the opening tag and its `</script>`, parsed, with the escaped `</`
/// put back. Also returns the page split around that element's text.
fn embedded(page: &str) -> (Value, String, String) {
    let start = page.find(OPEN).expect("the page has the data element") + OPEN.len();
    let end = start
        + page[start..]
            .find("</script>")
            .expect("the data element closes");
    let text = &page[start..end];
    assert!(
        !text.contains("</"),
        "the data element must escape `</` so it cannot close itself"
    );
    let value = serde_json::from_str(&text.replace("<\\/", "</")).expect("the data is JSON");
    (value, page[..start].to_string(), page[end..].to_string())
}

fn edits_json() -> Vec<Value> {
    let document: Value = serde_json::from_str(&read(&root().join(EDITS))).expect("edits.json");
    document["edits"].as_array().expect("edits").clone()
}

fn page_edits(data: &Value) -> Vec<Value> {
    data["edits"].as_array().expect("edits").clone()
}

fn edit<'a>(edits: &'a [Value], id: &str) -> &'a Value {
    edits
        .iter()
        .find(|e| e["id"] == id)
        .unwrap_or_else(|| panic!("no edit {id}"))
}

/// The line `req satisfy` printed for `src/bench.rs -> REQ-0010` in an edit's committed `satisfy.txt`, read here on its own.
fn committed_line(edit_id: &str) -> String {
    let text = read(&root().join(format!("docs/architecture/drift/{edit_id}/satisfy.txt")));
    let needle = format!("] {ELEMENT} -> {CLAIM}");
    let lines: Vec<&str> = text
        .lines()
        .filter(|l| l.starts_with('[') && l.contains(&needle))
        .collect();
    assert_eq!(
        lines.len(),
        1,
        "{edit_id}: one line for the link: {lines:?}"
    );
    lines[0].to_string()
}

#[test]
fn the_drift_page_is_current_with_the_tool() {
    let run = build(&root(), &["--check", PAGE]);
    assert_eq!(run.code, Some(0), "{}", run.said);
    assert!(run.said.contains("[CURRENT]"), "{}", run.said);
}

#[test]
fn a_hand_edited_page_is_stale_and_named() {
    let copy = Copy::new("stale");
    let page = copy.path(PAGE);
    let edited = read(&page).replacen("<h1>", "<h1 data-hand-edited=\"1\">", 1);
    assert_ne!(edited, read(&page), "the page has an <h1> to edit");
    fs::write(&page, edited).expect("edits the copy");
    let run = build(&copy.0, &["--check", PAGE]);
    assert_eq!(run.code, Some(1), "{}", run.said);
    assert!(
        run.said.contains("STALE") && run.said.contains(PAGE),
        "the stale page is named:\n{}",
        run.said
    );
    // A page that does not exist is stale too, never current.
    let missing = build(&copy.0, &["--check", "docs/nope.html"]);
    assert_eq!(missing.code, Some(1), "{}", missing.said);
}

/// The data tell the story of `edits.json` and nothing else: the same three edits, in order, the same statements, and for
/// each the line `req satisfy` printed, byte for byte.
#[test]
fn the_embedded_edits_are_edits_json_and_each_satisfy_line_is_the_committed_one() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    let want = edits_json();
    let got = page_edits(&data);
    assert_eq!(got.len(), 3, "three edits, three stories");
    assert_eq!(got.len(), want.len());
    for (g, w) in got.iter().zip(&want) {
        for key in ["id", "kind", "claim_id", "before", "after"] {
            assert_eq!(g[key], w[key], "edit {}: `{key}`", w["id"]);
        }
        let id = w["id"].as_str().expect("an id");
        assert_eq!(
            g["satisfy_line"].as_str().expect("a line"),
            committed_line(id),
            "edit {id}: the line is req satisfy's own"
        );
        assert_eq!(g["element"], ELEMENT);
    }
    assert_eq!(data["claim"]["id"], CLAIM);
    assert_eq!(data["claim"]["element"], ELEMENT);
    // The statement the page calls "before" is the one in the real claim file (never edited by the build).
    let claim = read(&root().join(format!("claims/{CLAIM}.yml")));
    let folded: String = claim
        .split("statement: >-\n")
        .nth(1)
        .expect("a folded statement")
        .lines()
        .take_while(|l| l.starts_with("  "))
        .map(str::trim)
        .collect::<Vec<_>>()
        .join(" ");
    for e in &got {
        assert_eq!(e["before"], folded.as_str());
    }
}

/// The three outcome words, matched to the three edits (a swap fails), and the direction `req compare` gave each.
#[test]
fn the_outcome_words_are_matched_to_reword_loosen_and_tighten() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    let got = page_edits(&data);
    for (id, kind, word, label, direction) in STORIES {
        let e = edit(&got, id);
        assert_eq!(e["kind"], kind, "{id}");
        assert_eq!(e["outcome"], word, "{id}: the outcome word");
        assert_eq!(e["outcome_label"], label, "{id}: the label");
        assert!(
            e["satisfy_line"]
                .as_str()
                .expect("a line")
                .starts_with(&format!("[{label}] {ELEMENT} -> {CLAIM}")),
            "{id}: {}",
            e["satisfy_line"]
        );
        assert_eq!(e["direction"], direction, "{id}: req compare's direction");
        let line = e["compare"]["line"].as_str().expect("req compare's line");
        assert!(
            line.ends_with(&format!(": {direction}")),
            "{id}: compare line {line}"
        );
        // Only the tightening is framed in red, and only that picture says so.
        let framed = id == "tightening";
        assert_eq!(
            e["frame"],
            if framed {
                Value::from("re-check: SUSPECT")
            } else {
                Value::Null
            },
            "{id}: the frame"
        );
    }
    // The meaning fingerprint moves for a loosening and a tightening, not for a re-word.
    let fp = |id: &str| -> (String, String) {
        let f = &edit(&got, id)["compare"]["fingerprints"];
        (
            f["before"].as_str().expect("before").to_string(),
            f["after"].as_str().expect("after").to_string(),
        )
    };
    let (a, b) = fp("cosmetic");
    assert_eq!(a, b, "a re-word keeps the fingerprint");
    for id in ["loosening", "tightening"] {
        let (a, b) = fp(id);
        assert_ne!(a, b, "{id} moves the fingerprint");
    }
}

/// The plain sentences are fixed template text keyed by the outcome word, and each agrees with ADR 0040 decision 3.
#[test]
fn each_outcome_sentence_agrees_with_adr_0040_and_sits_under_its_own_word() {
    let template = read(&root().join(TEMPLATE));
    let sentence = |key: &str| -> String {
        let lines: Vec<&str> = template
            .lines()
            .map(str::trim)
            .filter(|l| l.starts_with(&format!("{key}: '")))
            .collect();
        assert_eq!(lines.len(), 1, "one sentence keyed `{key}`: {lines:?}");
        lines[0].to_ascii_lowercase()
    };
    let holds = sentence("holds");
    let weakened = sentence("holds_weakened");
    let suspect = sentence("suspect");
    // holds: the same meaning fingerprint, no alarm.
    assert!(holds.contains("fingerprint") && holds.contains("unchanged"));
    assert!(holds.contains("no alarm"));
    assert!(!holds.contains("stricter") && !holds.contains("looser"));
    // holds (weakened): looser, not re-opened, reported by name.
    assert!(weakened.contains("looser"), "{weakened}");
    assert!(weakened.contains("not re-opened"), "{weakened}");
    assert!(weakened.contains("by name"), "{weakened}");
    assert!(!weakened.contains("must re-check"), "{weakened}");
    // suspect: stricter, a human re-checks and re-records, with the command that records it.
    assert!(suspect.contains("stricter"), "{suspect}");
    assert!(suspect.contains("re-check") && suspect.contains("re-record"));
    assert!(suspect.contains("req satisfy --record {element} {claim}"));
    assert!(!suspect.contains("looser"));
    // The SUSPECT definition, in plain words, and what a SUSPECT part does not mean.
    for needle in [
        "recorded against a claim whose meaning has since tightened or changed in another direction",
        "does not mean the part is wrong",
        "a person must re-check it and re-record the link",
    ] {
        assert!(template.contains(needle), "the template lacks: {needle}");
    }
    // The reword says the diagram is identical rather than showing a second copy, and only when the data say so.
    assert!(template.contains("diagram_unchanged"));
    // No other tool is named or compared on this page.
    let lower = template.to_ascii_lowercase();
    for other in [
        "doorstop",
        "openfasttrace",
        "doors",
        "polarion",
        "jama",
        "jira",
        "codebeamer",
        "reqif",
    ] {
        assert!(
            !lower.contains(other),
            "the page names another tool: {other}"
        );
    }
}

/// An outcome reaches the markup only through a closed list, as on the explorer.
#[test]
fn an_outcome_reaches_the_markup_only_through_a_closed_list() {
    let template = read(&root().join(TEMPLATE));
    assert!(
        template.contains("function outcomeClass("),
        "one place maps an outcome to a class"
    );
    assert!(template.contains("OUTCOME_CLASSES"), "the list is closed");
    assert_eq!(
        template.matches("o-' +").count() + template.matches("o-\" +").count(),
        0,
        "a data outcome is concatenated into a class name"
    );
    // The class list (double quoted) and the sentence list (single quoted) each name the three outcomes.
    for outcome in ["holds", "holds_weakened", "suspect"] {
        assert!(
            template.contains(&format!("{outcome}: \"o-")),
            "the class list names `{outcome}`"
        );
        assert!(
            template.contains(&format!("{outcome}: '")),
            "the sentence list names `{outcome}`"
        );
    }
    assert!(template.contains(".o-other"), "an unknown outcome is fixed");
}

/// *Falsification* 3 of the explorer, reused: nothing is fetched. `<a href>` may point anywhere; a script, style, font, image
/// or request may not.
fn leaks(text: &str) -> Vec<String> {
    fn remote(value: &str) -> bool {
        let value = value.trim().trim_matches(|c| c == '"' || c == '\'');
        let lower = value.to_ascii_lowercase();
        lower.starts_with("http://")
            || lower.starts_with("https://")
            || lower.starts_with("//")
            || lower.starts_with("ws:")
            || lower.starts_with("wss:")
    }
    // `n` characters from byte `at` (the template holds non-ASCII text, so never slice by bytes).
    fn from(text: &str, at: usize, n: usize) -> String {
        text[at..].chars().take(n).collect()
    }
    let mut found = Vec::new();
    let lower = text.to_ascii_lowercase();
    for key in ["src=", "srcset=", "poster=", "data-src="] {
        for (at, _) in lower.match_indices(key) {
            // Only an attribute (a space or a tag name before it), not a JS property such as `x.src=`.
            let before = lower[..at].chars().next_back().unwrap_or(' ');
            if before == '.' || before.is_ascii_alphanumeric() || before == '_' {
                continue;
            }
            let value = from(text, at + key.len(), 160);
            if remote(&value) {
                found.push(from(text, at, 70));
            }
        }
    }
    for (at, _) in lower.match_indices("<link") {
        let tag = &text[at..at + text[at..].find('>').unwrap_or(text.len() - at)];
        let tag_lower = tag.to_ascii_lowercase();
        if let Some(h) = tag_lower.find("href=")
            && remote(&from(tag, h + 5, 160))
        {
            found.push(tag.to_string());
        }
    }
    for (at, _) in lower.match_indices("url(") {
        if remote(&from(text, at + 4, 80)) {
            found.push(from(text, at, 40));
        }
    }
    // Whitespace is dropped for the needles, so `new  Worker (` and `import (` are seen as `newworker(` and `import(`.
    let squeezed: String = lower.chars().filter(|c| !c.is_whitespace()).collect();
    for needle in [
        "@import",
        "fetch(",
        "xmlhttprequest",
        "websocket(",
        "eventsource(",
        "sendbeacon",
        "importscripts",
        "newworker(",
        "newsharedworker(",
        "serviceworker",
        "import(",
        "<iframe",
        "<frame",
        "<object",
        "<embed",
    ] {
        if squeezed.contains(needle) {
            found.push(needle.to_string());
        }
    }
    for (at, _) in lower.match_indices("data=") {
        let before = lower[..at].chars().next_back().unwrap_or(' ');
        if !(before == '.' || before.is_ascii_alphanumeric() || before == '_' || before == '-')
            && remote(&from(text, at + 5, 160))
        {
            found.push(from(text, at, 70));
        }
    }
    found
}

#[test]
fn the_page_loads_nothing_over_the_network() {
    let page = read(&root().join(PAGE));
    let (_, before, after) = embedded(&page);
    let leaked = leaks(&format!("{before}{after}"));
    assert!(
        leaked.is_empty(),
        "the page reaches the network: {leaked:?}"
    );
    let template = read(&root().join(TEMPLATE));
    let leaked = leaks(&template);
    assert!(
        leaked.is_empty(),
        "the template reaches the network: {leaked:?}"
    );
    // Stricter than the attribute scan: the template names no remote address at all (the links a reader follows, GitHub
    // among them, come from the data, which is not code). Its one URL may be the SVG namespace, an identifier never fetched.
    for template_or_page in [template.clone(), format!("{before}{after}")] {
        let urls: Vec<&str> = template_or_page
            .match_indices("http")
            .map(|(at, _)| &template_or_page[at..])
            .filter(|rest| rest.starts_with("http://") || rest.starts_with("https://"))
            .filter(|rest| !rest.starts_with("http://www.w3.org/2000/svg"))
            .map(|rest| &rest[..rest.len().min(60)])
            .collect();
        assert!(
            urls.is_empty(),
            "the template names a remote address (only the SVG namespace is allowed): {urls:?}"
        );
    }
    // The detector sees what it should.
    assert!(!leaks("<script src=\"https://cdn.example.org/x.js\"></script>").is_empty());
    assert!(!leaks("<link rel=\"stylesheet\" href=\"//cdn.example.org/x.css\">").is_empty());
    assert!(!leaks("a{background:url(https://example.org/x.png)}").is_empty());
    assert!(leaks("<a href=\"https://example.org/\">x</a>").is_empty());
    for sample in [
        "new Worker('https://cdn.example.org/w.js')",
        "navigator.serviceWorker.register('/sw.js')",
        "import('https://cdn.example.org/m.js')",
        "<iframe src=\"https://example.org/\"></iframe>",
        "<object data=\"https://example.org/x.swf\"></object>",
        "<embed src=\"//example.org/x\">",
        "importScripts('x.js')",
    ] {
        assert!(!leaks(sample).is_empty(), "the detector missed: {sample}");
    }
    assert!(leaks("an important(thing) and data-k=\"x\"").is_empty());
}

fn png_size(path: &Path) -> Option<(u32, u32, usize)> {
    let bytes = fs::read(path).ok()?;
    if bytes.len() < 24 || bytes[..8] != [0x89, b'P', b'N', b'G', 0x0d, 0x0a, 0x1a, 0x0a] {
        return None;
    }
    let word =
        |at: usize| u32::from_be_bytes([bytes[at], bytes[at + 1], bytes[at + 2], bytes[at + 3]]);
    Some((word(16), word(20), bytes.len()))
}

/// Every picture the page names exists and is a PNG; the three share one pixel size, so the diagram sits in the same place in
/// each (the one changed box is then the only thing that moves); the re-word shows no second copy of the diagram.
#[test]
fn the_images_it_references_exist_and_are_one_size() {
    let page = read(&root().join(PAGE));
    let (data, before, after) = embedded(&page);
    let docs = root().join("docs");
    let mut named: Vec<String> = Vec::new();
    named.push(
        data["before"]["image"]
            .as_str()
            .expect("the before image")
            .to_string(),
    );
    for e in page_edits(&data) {
        if let Some(image) = e["image"].as_str() {
            named.push(image.to_string());
        }
    }
    assert_eq!(
        named.len(),
        3,
        "before, loosening and tightening: {named:?}"
    );
    let mut sizes = Vec::new();
    for image in &named {
        assert!(
            !image.starts_with('/') && !image.contains("://") && !image.contains(".."),
            "an image is a relative path under docs/: {image}"
        );
        let (w, h, bytes) = png_size(&docs.join(image))
            .unwrap_or_else(|| panic!("{image} is not a PNG under docs/"));
        assert!(w >= 1000 && h >= 700, "{image} is {w}x{h}");
        assert!(
            bytes < 600 * 1024,
            "{image} is {bytes} bytes (under ~600 KB)"
        );
        sizes.push((w, h));
    }
    assert!(
        sizes.windows(2).all(|pair| pair[0] == pair[1]),
        "the three pictures must have identical pixel dimensions (the header is read): {named:?} {sizes:?}"
    );
    let got = page_edits(&data);
    assert_eq!(data["before"]["image"], "architecture/drift/req-before.png");
    assert_eq!(
        edit(&got, "tightening")["image"],
        "architecture/drift/req-tightening.png"
    );
    assert_eq!(
        edit(&got, "loosening")["image"],
        "architecture/drift/req-loosening.png"
    );
    // The README's pictures are not the page's: the page no longer shows the tighter overview crop.
    for image in &named {
        assert_ne!(image, "architecture/req-overview.png");
    }
    // The re-word's diagram is the one before, so the page says so instead of showing a duplicate.
    let cosmetic = edit(&got, "cosmetic");
    assert!(cosmetic["image"].is_null(), "no second copy of the diagram");
    assert_eq!(cosmetic["diagram_unchanged"], true);
    for id in ["loosening", "tightening"] {
        assert_eq!(edit(&got, id)["diagram_unchanged"], false, "{id}");
    }
    // The template and the page around the data name no picture of their own (the data is the only place they come from).
    for around in [&before, &after] {
        assert!(
            !around.to_ascii_lowercase().contains(".png"),
            "a picture is named outside the data"
        );
    }
    // The three pictures differ from each other (each was rendered, none copied).
    let bytes = |name: &str| fs::read(docs.join(name)).expect("an image");
    for (a, b) in [
        (&named[0], &named[1]),
        (&named[0], &named[2]),
        (&named[1], &named[2]),
    ] {
        assert_ne!(bytes(a), bytes(b), "{a} and {b} are the same bytes");
    }
}

/// The step 2 `req compare` output is shown as req printed it, and when it carries a pin note the template adds one plain
/// sentence under it: the pin is the claim's own, the copy edited only the statement, and a real author would update the pin.
#[test]
fn the_pin_note_is_kept_verbatim_and_explained_in_one_plain_sentence() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    let got = page_edits(&data);
    let note = "a pin disagrees with its claim's parse";
    for id in ["loosening", "tightening"] {
        let notes = edit(&got, id)["compare"]["notes"]
            .as_array()
            .expect("notes");
        assert_eq!(notes.len(), 1, "{id}: req compare prints one note");
        let text = notes[0].as_str().expect("a note");
        assert!(text.starts_with(note), "{id}: req's own words: {text}");
        assert!(text.contains("run `req canon` before trusting the classification"));
    }
    assert!(
        edit(&got, "cosmetic")["compare"]["notes"]
            .as_array()
            .expect("notes")
            .is_empty(),
        "a re-word carries no note"
    );
    // The pin the sentence speaks of is the real claim's, read here from the file, and the build never edits it.
    let claim = read(&root().join(format!("claims/{CLAIM}.yml")));
    assert!(
        claim.contains("pins:\n  value: \"0.3\""),
        "the claim pins the value 0.3"
    );
    assert_eq!(data["claim"]["pins"]["value"], "0.3");
    let template = read(&root().join(TEMPLATE));
    let line = template
        .lines()
        .map(str::trim)
        .find(|l| l.starts_with("var PIN_NOTE = '"))
        .expect("the template holds the sentence in one place");
    let lower = line.to_ascii_lowercase();
    for needle in [
        "pins the value {value}",
        "only the statement was edited",
        "no longer matches",
        "update or remove the pin",
    ] {
        assert!(
            lower.contains(needle),
            "the sentence lacks `{needle}`: {line}"
        );
    }
    assert!(
        template.contains("compare.notes.length"),
        "the sentence is keyed on the note's presence"
    );
}

