/// The changed words are marked from the two statements alone: the unmarked words are common to both.
#[test]
fn the_changed_words_are_exactly_the_words_that_differ() {
    let (data, _, _) = embedded(&read(&root().join(PAGE)));
    let got = page_edits(&data);
    let runs = |e: &Value, side: &str| -> Vec<(String, bool)> {
        e["diff"][side]
            .as_array()
            .unwrap_or_else(|| panic!("diff.{side}"))
            .iter()
            .map(|r| {
                (
                    r["t"].as_str().expect("text").to_string(),
                    r["c"].as_bool().expect("changed"),
                )
            })
            .collect()
    };
    let expect = [
        ("cosmetic", "at most", "no more than"),
        ("loosening", "0.30", "0.40"),
        ("tightening", "0.30", "0.20"),
    ];
    for (id, was, now) in expect {
        let e = edit(&got, id);
        let join = |side: &str| {
            runs(e, side)
                .iter()
                .map(|(t, _)| t.clone())
                .collect::<Vec<_>>()
                .join(" ")
        };
        assert_eq!(
            join("before"),
            e["before"].as_str().expect("before"),
            "{id}"
        );
        assert_eq!(join("after"), e["after"].as_str().expect("after"), "{id}");
        let changed = |side: &str| -> String {
            runs(e, side)
                .into_iter()
                .filter(|(_, c)| *c)
                .map(|(t, _)| t)
                .collect::<Vec<_>>()
                .join(" | ")
        };
        assert_eq!(changed("before"), was, "{id}: the words that went");
        assert_eq!(changed("after"), now, "{id}: the words that came");
    }
}

/// The page is the template with the data inserted, nothing else; two builds are the same bytes; the build never edits a claim.
#[test]
fn the_page_is_the_template_around_the_data_and_two_builds_agree() {
    let template = read(&root().join(TEMPLATE));
    assert_eq!(
        template.matches(TOKEN).count(),
        1,
        "the template names the data's place exactly once"
    );
    assert!(
        template.contains(&format!("{OPEN}{TOKEN}</script>")),
        "the token sits inside the data element"
    );
    let page = read(&root().join(PAGE));
    let (_, before, after) = embedded(&page);
    let (template_before, template_after) = template.split_once(TOKEN).expect("the token");
    assert_eq!(before, template_before, "the bytes before the data");
    assert_eq!(after, template_after, "the bytes after the data");

    let claim_before = fs::read(root().join(format!("claims/{CLAIM}.yml"))).expect("the claim");
    let dir = std::env::temp_dir().join(format!("req-drift-twice-{}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("makes the dir");
    let first = dir.join("first.html");
    let second = dir.join("second.html");
    for out in [&first, &second] {
        let run = build(&root(), &["--out", out.to_str().expect("a path")]);
        assert_eq!(run.code, Some(0), "{}", run.said);
    }
    let a = fs::read(&first).expect("first build");
    let b = fs::read(&second).expect("second build");
    let _ = fs::remove_dir_all(&dir);
    assert_eq!(a, b, "two builds over one repository differ");
    assert_eq!(a, page.as_bytes(), "a build is the committed page");
    assert_eq!(
        claim_before,
        fs::read(root().join(format!("claims/{CLAIM}.yml"))).expect("the claim"),
        "the build never edits this checkout's claims"
    );
}

/// How many `<script>` elements the browser's tokenizer would see: a start tag, then raw text up to the next `</script`.
fn script_elements(page: &str) -> usize {
    let lower = page.to_ascii_lowercase();
    let mut count = 0;
    let mut at = 0;
    while let Some(found) = lower[at..].find("<script") {
        let start = at + found;
        let next = lower[start + 7..].chars().next().unwrap_or(' ');
        if next == '>' || next == '/' || next.is_whitespace() {
            count += 1;
            at = match lower[start..].find("</script") {
                Some(end) => start + end + 8,
                None => return count,
            };
        } else {
            at = start + 7;
        }
    }
    count
}

/// Markup in a statement and in a `req satisfy` line stays data: it comes back byte for byte and adds no element.
#[test]
fn markup_in_a_statement_stays_data_and_adds_no_element() {
    let payload = "</script><script>alert(1)</script> <!--";
    let copy = Copy::new("markup");
    // The claim, the edits and the committed `satisfy.txt` all carry the payload, on the copy only.
    let claim = copy.path(&format!("claims/{CLAIM}.yml"));
    let text = read(&claim);
    let marker = "parity corpus at v0.";
    assert!(text.contains(marker), "the claim ends its statement here");
    fs::write(
        &claim,
        text.replacen(marker, &format!("{marker} {payload}"), 1),
    )
    .expect("edits the copy's claim");
    let edits_path = copy.path(EDITS);
    let edits = read(&edits_path);
    let with_payload = edits.replace(
        "at v0.\"",
        &format!("at v0. {}\"", payload.replace('"', "\\\"")),
    );
    assert_ne!(edits, with_payload);
    fs::write(&edits_path, with_payload).expect("edits the copy's edits.json");
    let satisfy = copy.path("docs/architecture/drift/cosmetic/satisfy.txt");
    let line = read(&satisfy);
    let marked = line.replacen(
        &format!("[HOLDS] {ELEMENT} -> {CLAIM}\n"),
        &format!("[HOLDS] {ELEMENT} -> {CLAIM}: {payload}\n"),
        1,
    );
    assert_ne!(line, marked);
    fs::write(&satisfy, marked).expect("edits the copy's satisfy.txt");

    let run = build(&copy.0, &["--out", "built.html"]);
    assert_eq!(run.code, Some(0), "{}", run.said);
    let page = read(&copy.path("built.html"));
    let (data, _, _) = embedded(&page);
    let got = page_edits(&data);
    let cosmetic = edit(&got, "cosmetic");
    assert!(
        cosmetic["before"]
            .as_str()
            .expect("before")
            .contains(payload),
        "the statement comes back unchanged"
    );
    assert!(
        cosmetic["after"].as_str().expect("after").contains(payload),
        "the statement comes back unchanged"
    );
    assert!(
        cosmetic["satisfy_line"]
            .as_str()
            .expect("line")
            .ends_with(payload),
        "req's line comes back unchanged"
    );
    let template = read(&root().join(TEMPLATE));
    assert_eq!(
        script_elements(&page),
        script_elements(&template),
        "a statement added a script element"
    );
    assert_eq!(
        page.matches("<!--").count(),
        template.matches("<!--").count(),
        "a `<!--` reached the page"
    );
    let start = page.find(OPEN).expect("the data element") + OPEN.len();
    let end = start + page[start..].find("</script>").expect("it closes");
    assert!(!page[start..end].contains("<!--"));
    // The tokenizer used here is not blind: the unescaped payload would be seen as extra elements.
    assert!(script_elements(&format!("{template}{payload}")) > script_elements(&template));
    // The template renders the data as text, never as markup.
    for risky in [
        "innerHTML",
        "outerHTML",
        "insertAdjacentHTML",
        "document.write",
    ] {
        assert!(!template.contains(risky), "the template uses {risky}");
    }
}

/// An edit whose committed output is not the one it expects is UNVERIFIABLE (exit 3, named), never a current page, and a build
/// refuses a picture that is not there.
#[test]
fn a_demonstration_that_disagrees_with_itself_is_unverifiable_never_current() {
    // `edits.json` expects the loosening to hold (weakened); a committed line that says SUSPECT contradicts it.
    let copy = Copy::new("disagree");
    let satisfy = copy.path("docs/architecture/drift/loosening/satisfy.txt");
    let text = read(&satisfy);
    let swapped = text.replacen(
        "[HOLDS (weakened)] src/bench.rs -> REQ-0010",
        "[SUSPECT] src/bench.rs -> REQ-0010",
        1,
    );
    assert_ne!(text, swapped);
    fs::write(&satisfy, swapped).expect("edits the copy");
    for mode in ["--check", "--out"] {
        let target = if mode == "--check" { PAGE } else { "x.html" };
        let run = build(&copy.0, &[mode, target]);
        assert_eq!(run.code, Some(3), "{mode}: {}", run.said);
        assert!(
            run.said.contains("UNVERIFIABLE") && run.said.contains("loosening"),
            "{mode}: the edit is named:\n{}",
            run.said
        );
    }
    assert!(!copy.path("x.html").exists(), "nothing was written");

    // A picture the page would reference but that is not there.
    let copy = Copy::new("no-image");
    fs::remove_file(copy.path("docs/architecture/drift/req-loosening.png")).expect("removes");
    let run = build(&copy.0, &["--check", PAGE]);
    assert_eq!(run.code, Some(3), "{}", run.said);
    assert!(
        run.said.contains("UNVERIFIABLE") && run.said.contains("req-loosening.png"),
        "the missing picture is named:\n{}",
        run.said
    );

    // `req` cannot run: nothing was compared.
    let copy = Copy::new("no-req");
    let interpreter = python3();
    let output = Command::new(interpreter)
        .arg(BUILDER)
        .args(["--req", "/nonexistent/req", "--check", PAGE])
        .current_dir(&copy.0)
        .env_remove("REQ_ROOT")
        .output()
        .expect("runs the builder");
    assert_eq!(output.status.code(), Some(3));
    assert!(String::from_utf8_lossy(&output.stderr).contains("UNVERIFIABLE"));
}

/// `--out` that cannot write is UNVERIFIABLE with its reason, never a traceback that exits 1; one invocation names one mode.
#[test]
fn an_unwritable_out_is_exit_3_and_two_modes_are_a_usage_error() {
    let dir = std::env::temp_dir().join(format!("req-drift-unwritable-{}", std::process::id()));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("makes the dir");
    let to_dir = build(&root(), &["--out", dir.to_str().expect("a path")]);
    let missing = dir.join("no").join("such").join("page.html");
    let to_missing = build(&root(), &["--out", missing.to_str().expect("a path")]);
    let _ = fs::remove_dir_all(&dir);
    for run in [&to_dir, &to_missing] {
        assert_eq!(run.code, Some(3), "{}", run.said);
        assert!(
            run.said.contains("UNVERIFIABLE") && run.said.contains("cannot write"),
            "the reason is named:\n{}",
            run.said
        );
        assert!(!run.said.contains("Traceback"), "{}", run.said);
    }
    for args in [
        ["--out", "a.html", "--check", "b.html"],
        ["--check", "b.html", "--out", "a.html"],
        ["--out", "a.html", "--out", "b.html"],
        ["--check", "a.html", "--check", "b.html"],
    ] {
        let run = build(&root(), &args);
        assert_eq!(run.code, Some(2), "{args:?}: {}", run.said);
        assert!(run.said.contains("usage"), "{args:?}: {}", run.said);
    }
    assert_eq!(build(&root(), &[]).code, Some(2));
    assert!(!root().join("a.html").exists() && !root().join("b.html").exists());
}

